contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address operator, address from, uint256 tokenId, bytes calldata data) public {
        bytes4 retval;
        bool reverted;
        try c.onERC721Received(operator, from, tokenId, data) returns (bytes4 r) {
            retval = r;
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted || retval == 0x150b7a02);
    }
}

